instances.text:
rule { true #Equals isInt(V:Val) }
    => #Exists I:Int . { V #Equals I }
    [simplification]

rule { numVals(@NS:NumSeq) #Equals .ValSeq }
    => { @NS #Equals .NumSeq }
    [simplification]

rule { numVals(@NS1:NumSeq) #Equals numVals(@NS2:NumSeq) }
    => { @NS1 #Equals @NS2 }
    [simplification]

rule { numVals(@NS:NumSeq)
         #Equals vCons(@I:Int, numVals(@R:NumSeq)) }
    => { @NS #Equals nInt(@I, @R) }
    [simplification]

rule { numVals(@NS:NumSeq)
         #Equals vCons(@F:Float, numVals(@R:NumSeq)) }
    => { @NS #Equals nFloat(@F, @R) }
    [simplification]

rule #Ceil({@V:Val}:>Str)
    => (
         { definedProjectStr(@V) #Equals true }
         #And #Ceil(@V)
       )
    [simplification]

rule { @V:Val #Equals projectStrTotal(@V) }
    => { isStringVal(@V) #Equals true }
    [simplification]

rule { @V:Val #Equals str(codesProject(@V)) }
    => { isStringVal(@V) #Equals true }
    [simplification]

